// Shared loader for rust/reference/params.json (generated by tools/export_reference.py).
#![allow(dead_code)]

use serde::Deserialize;

#[derive(Deserialize)]
pub struct Spec {
    pub name: String,
    pub default: f64,
    pub lo: f64,
    pub hi: f64,
    pub curve: String,
    pub unit: String,
    pub smooth_ms: f64,
    pub clamp_in: Vec<f64>,
    pub clamp_out: Vec<f64>,
    #[serde(default)]
    pub to_norm_out: Vec<f64>,
    #[serde(default)]
    pub from_norm_in: Vec<f64>,
    #[serde(default)]
    pub from_norm_out: Vec<f64>,
}

#[derive(Deserialize)]
pub struct SmootherCase {
    pub start: f64,
    pub target: f64,
    pub sample_rate: f64,
    pub time_ms: f64,
    pub steps: Vec<i64>,
    pub values: Vec<f64>,
}

#[derive(Deserialize)]
pub struct Reference {
    pub version: u32,
    pub synth: Vec<Spec>,
    pub drums: Vec<Spec>,
    pub smoother: Vec<SmootherCase>,
}

pub fn load() -> Reference {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/../reference/params.json");
    let text = std::fs::read_to_string(path).expect("reference file");
    let r: Reference = serde_json::from_str(&text).expect("valid reference");
    assert_eq!(r.version, 1);
    r
}

pub fn close(a: f64, b: f64) -> bool {
    a == b || (a - b).abs() <= 1e-12 * a.abs().max(b.abs())
}
